import Foundation

/// The Macedonian passages.
///
/// Written rather than translated: about sixty of the English passages
/// are etymologies of English words and are simply false in any other
/// language, so this bank comes from its own word histories, its own
/// literature and its own proverbs.
extension Quotes {
    static let macedonian: [Passage] = [
        // MARK: Beginnings
        Passage(text: "Никнување: мигот во кој семето престанува да биде залиха и станува растение. По тој чекор нема враќање назад.", source: "Ботаника", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Првите два листа се свиткани во семето долго пред да постои светлина што ќе ги отвори.", source: "Ботаника", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Пилето ја крши лушпата со мала бела израстка на врвот од клунот. Таа отпаѓа неколку дена откако ќе излезе и повеќе не му треба.", source: "Зоологија", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Пупката се отвора еднаш. Минута порано била затворена, минута подоцна веќе не може да се затвори.", source: "Ботаника", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Аирлија да е: се кажува кога некој влегува во нова куќа или отвора дуќан. Од арапското хаир, добро — реченица за почеток, не за крај.", source: "Турцизам во македонскиот", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Мугра е зборот за првата светлина пред изгрев. Има и множина, мугри, иако станува збор за нешто што се случува еднаш на ден.", source: "Македонски јазик", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Кокичето цвета додека уште има снег. Пупката му е готова од претходната есен и цела зима чека под земја, склопена.", source: "Ботаника", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Орото почнува од еден. Првиот тргнува, а другите се фаќаат по него, така што редот на почнувањето останува видлив цела песна.", source: "Народна музика", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Мирисот на првиот дожд по суша доаѓа од масла собрани во сувата почва и од нешто што го лачат почвените бактерии.", source: "Хемија", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Семето прво спушта корен, па дури потоа стебло. Првото нешто што го прави растението е да се задржи на место.", source: "Ботаника", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Ајде: зборот со кој почнува речиси сѐ — одење, играње, работа. Дојден од турското хајди, а останал како покана за тргнување.", source: "Турцизам во македонскиот", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Јајцето на пеперугата се лепи од долната страна на листот што гасеницата ќе го јаде. Изборот на лист е направен пред да има кој да јаде.", source: "Ентомологија", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Вардар почнува кај Вруток под Шар Планина, од извор што може да се прекрачи, и завршува во Егејско Море.", source: "Географија", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Мовот се фаќа за гол камен и нема корени. По него доаѓа првата прст, а по прста сѐ друго.", source: "Екологија", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Лишајот на карпа расте по неколку милиметри годишно, па дамка колку дланка може да е стара со векови.", source: "Ботаника", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Бигорот се создава кога варовникот што водата го носи растворен се таложи врз мов и гранки. Така водата си ѕида праг сама на себе.", source: "Геологија", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "За едно кило мед пчелите облетуваат милиони цветови, а една пчела за целиот свој живот собира помалку од една лажичка.", source: "Пчеларство", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Тумбите во Пелагонија се ридчиња направени од луѓе: секое село подигнато врз урнатините на претходното го крева теренот по малку.", source: "Археологија", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Лозата се сади како гранче отсечено од друга лоза. Од нешто колку дланка излегува род што трае децении.", source: "Лозарство", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Секоја снегулка почнува од честичка прав околу која се фаќа првиот мраз. Без неа водата во облакот останува течна и под нулата.", source: "Метеорологија", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Молика: борот на Пелистер носи по пет иглички во сноп, расте бавно и живее долго. Најстарите стебла ги паметат сите под нив.", source: "Ботаника", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Една нива грутлива си изникна трева, на тревата дваесет браќа.", source: "Народна гатанка, одговор: класје", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Водата од Преспанското Езеро поминува низ варовникот на Галичица и излегува во Охридското. Двете езера се спојуваат внатре во планината.", source: "Хидрологија", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Од една матица со шака пчели за едно лето станува рој што ја исполнува кошницата. Ништо однадвор не е донесено освен цветот.", source: "Пчеларство", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Кога се ора, првата бразда се вади права колку што може, зашто по неа се мери секоја наредна до крајот на нивата.", source: "Земјоделство", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Лозјето се сади еднаш. Редот и растојанието се одлучуваат првиот ден и траат колку самото лозје.", source: "Лозарство", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Во ботаниката важи првото објавено име. Ако подоцна некој смисли подобро, сепак останува првото; правилото се вика приоритет.", source: "Номенклатура", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Со среќа: се кажува кога некој почнува работа, гради куќа или тргнува на пат. Не е поздрав туку желба врзана за почетокот.", source: "Македонски јазик", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Кумот што ќе го држи детето на крштевка останува кум цел живот, а кумството се пренесува меѓу двете куќи со генерации.", source: "Народен обичај", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Договор: до и говор, зборување доведено до некаде. Работата не е во потписот туку во тоа што повеќе нема што да се додаде.", source: "Етимологија", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Македонската азбука е утврдена во 1945 и има триесет и една буква. На секој глас му припадна по една, па зборот се пишува како што се слуша.", source: "Историја на јазикот", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Првото млеко по јагнењето е густо и жолто, поинакво од сето подоцнежно. Без него јагнето нема со што да се брани.", source: "Овчарство", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Детето често го носи името на дедото или бабата, па во едно семејство истото име се враќа на секое второ колено.", source: "Народен обичај", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Гнездото на штркот се доградува секое лето врз лањското. По неколку десетлетија тежи колку што куќата под него може да поднесе.", source: "Орнитологија", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "На Водици крстот се фрла во студена вода и кој прв ќе го извади, за него се вели дека годината му е добра уште од јануари.", source: "Народен обичај", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Тестото се сече на погача пред да влезе во огништето. Каде ќе се пресече одлучува како ќе се дели подоцна на масата.", source: "Готварство", theme: .beginnings, subtheme: .whatAStartSettles),
        // MARK: Waiting
        Passage(text: "Мирување: семе што не никнува иако сѐ околу него е како што треба, задржано однатре додека нешто во самото него не се промени.", source: "Ботаника", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Некои семиња не никнуваат додека не поминат низ студ. Топлината сама не им е доволна; им треба и доказ дека зимата навистина поминала.", source: "Ботаника", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Обвивката на некои семиња е толку тврда што водата не влегува. Ги отвора мраз, оган или поминување низ стомакот на животно.", source: "Ботаника", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Пупките на дабот се готови уште во јули и стојат затворени низ целата зима. Дрвото има подготвена пролет осум месеци однапред.", source: "Шумарство", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Луковицата под земја е цел иден цвет, свиткан и одложен, со сопствена храна покрај себе за денот кога ќе тргне.", source: "Ботаника", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Лилјакот што презимува ја спушта топлината на телото речиси до онаа на пештерата и останува така со месеци, без да јаде.", source: "Зоологија", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Сувиот квасец е жив, но со толку малку вода во себе што не може ништо да работи. Врати му ја водата и продолжува од каде застанал.", source: "Микробиологија", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Во почвата под една ливада лежат семиња на растенија што одамна не се гледаат горе. Некои чекаат орање, некои чекаат оган.", source: "Екологија", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Во кожурецот однадвор не се случува ништо. Внатре речиси сѐ се разградува и се сложува пак, во друг ред.", source: "Ентомологија", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Трпеж и трпи стојат на еден корен. Не значат чекање туку носење на тежината додека таа трае.", source: "Македонски јазик", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Смолата на боровината затвора рана на дрвото и се стврднува врз неа. Она што ја држи раната затворена го држи и она што влегло внатре.", source: "Шумарство", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Пченицата посеана наесен никнува, па застанува и презимува зелена под снегот. Тој застој ѝ е потребен за да класи.", source: "Земјоделство", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Дренот цвета во февруари, кога уште ништо друго не цвета, а плодот му зрее дури наесен. Најраниот цвет носи најдоцнежен плод.", source: "Дрен", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Охридското Езеро се брои во милиони години и затоа во него живеат риби и полжави што ги нема на ниедно друго место.", source: "Лимнологија", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Јагулата поминува десетина години во езерото пред да тргне назад кон морето во кое се измолила. Никој не ја видел како се враќа втор пат.", source: "Ихтиологија", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Бели пари за црни дни.", source: "Пословица, Зборник на Миладиновци, 1861", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Со една ластоица не идет лето.", source: "Пословица, Зборник на Миладиновци, 1861", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Зимницата се прави во септември за јануари. Полиците во визбата се календар што се чита наназад.", source: "Готварство", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Кашкавалот стои во визба со месеци и се врти на секои неколку дена. Вкусот што го бараме не постои во млекото од кое е направен.", source: "Млекарство", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Костеновото дрво не раѓа сериозно пред петнаесеттата година, па оној што го садел ретко е оној што прв ќе го обере.", source: "Шумарство", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Вранецот се остава во дабово буре по неколку години. Работата на едната есен се проверува дури во некоја подоцнежна.", source: "Лозарство", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Мозаиците во Хераклеја лежеле под земја векови и излегле речиси цели. Истата земја што ги покрила ги и зачувала.", source: "Археологија", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Кога нивото на Мавровското Езеро ќе падне доволно ниско, од водата излегува стара црква. Некои години не излегува воопшто.", source: "Географија", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Смоквата раѓа двапати во годината, но вториот род зрее толку доцна што во ладна есен воопшто не стигнува да созрее.", source: "Смоква", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Сеир: гледање заради самото гледање, без намера да се пречи. Од турското сејир, а во македонскиот останало како начин да се помине попладне.", source: "Турцизам во македонскиот", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Чардакот е отворениот кат над дворот, направен за да се седи и да се гледа надолу по сокакот. Куќа со просторија чија работа е гледањето.", source: "Народна архитектура", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Сивата чапја стои во плитко без да мрдне толку долго што рибите околу неа престануваат да ја сметаат за нешто живо.", source: "Орнитологија", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Овчарот на бачило не ги тера овците. Работата му е да стои и да брои, зашто важно е да се забележи која недостасува.", source: "Овчарство", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Слабите ѕвезди се гледаат подобро ако не гледаш право во нив. Работ на окото фаќа послаба светлина од средината.", source: "Астрономија", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Шолјата се превртува врз чинивчето и се остава да се исуши. Дури потоа се гледа што останало по ѕидовите.", source: "Народен обичај", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Низите пиперки под стреата стојат цела есен пред очите на сите. Сушењето не е работа што ја правиш, туку што ја гледаш.", source: "Готварство", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Над клисурата Демир Капија птиците селици минуваат по иста линија секоја есен, па оној што сака да ги изброи стои на исто место.", source: "Орнитологија", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Луѓето седат пред огништето со часови иако од тоа ништо не излегува. Огнот и водата се гледаат на ист начин, без причина и без крај.", source: "Народен обичај", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Ѕидарот пред да ѕида стои и гледа во купот камења. Тој што ќе го најде вистинскиот прв, помалку го крши остатокот.", source: "Занает", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Штркот на оџак стои на една нога со часови. Другата ја крие во перјето зашто така губи помалку топлина.", source: "Штрк", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Пред да падне град небото над Пелагонија прво станува зеленикаво. Селаните го знаат тоа гледање и излегуваат да го проверат.", source: "Метеорологија", theme: .waiting, subtheme: .standingAndWatching),
        // MARK: Renewal
        Passage(text: "Ако пасат тревата, корењата стојат.", source: "Пословица, Зборник на Миладиновци, 1861", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Ливадата се коси двапати во лето и станува побогата од тоа. Онаа што со години никој не ја коси се затвора сама врз себе.", source: "Екологија", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Врбата отсечена до пенушка пушта по десетина нови прачки од истото место. Оттаму доаѓаат плетот и кошницата.", source: "Шумарство", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Лозата се реже секоја зима до неколку очи. Нережената дава повеќе лист и помалку грозје, па режењето не е одземање.", source: "Лозарство", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Од секое тесто се остава грутка за следното. Лебот што се меси денес почнал многу порано и обично во туѓа куќа.", source: "Готварство", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Салатата и спанаќот се берат лист по лист однадвор кон средината. Средината останува и продолжува да пушта.", source: "Градинарство", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Од пенушка на отсечен даб излегуваат нови изданоци. Иста подземна основа може да надживее неколку дрвја над себе.", source: "Шумарство", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Овцата се стриже еднаш годишно и волната се враќа. Тоа што се зема од неа не ѝ се одзема.", source: "Овчарство", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Трската покрај Дојранското Езеро се коси наесен, а напролет никнува погуста отколку што била.", source: "Ботаника", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Кај некои борови шишарките остануваат затворени со години и се отвораат дури откако оган ќе помине преку нив.", source: "Шумарство", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Гуштерот ја остава опашката во раката што го фатила и пушта нова. Новата не е иста како старата ниту одвнатре, но служи.", source: "Зоологија", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Полето со детелина се заорува во земјата наместо да се собере. Она што се врти назад во почвата ја храни следната култура.", source: "Земјоделство", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "На први март се врзува конец од бело и црвено на рака. Се носи додека не се види штрк или расцветано дрво, и тогаш се остава на гранка.", source: "Мартинки, народен обичај", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Од Ѓурѓовден до Митровден трае овчарската година. Двата дена стојат на спротивни страни од календарот и меѓу нив е сето пасење.", source: "Овчарство", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "На Ѓурѓовден се станува пред изгрев и лицето се мие со роса, а зелена гранка се закачува над вратата.", source: "Народен обичај", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "На Бадник во огништето влегува дебела гранка што гори преку ноќ, а искрите што прскаат од неа се бројат за добра година.", source: "Народен обичај", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Во новогодишната погача се крие паричка. Лебот се дели на сите во куќата, и на самата куќа ѝ се остава парче.", source: "Народен обичај", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Ластовицата се враќа во истата штала и често во истото гнездо, по неколку илјади километри и цела зима меѓу.", source: "Орнитологија", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Листот наесен не се обојува. Тој ја губи зелената боја, а жолтото стоело таму цело лето, покриено.", source: "Ботаника", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Кога ќе замириса на печени пиперки по маалото, тоа е поточен знак за септември отколку што е календарот.", source: "Готварство", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Во суво лето децата се облекуваат во зеленило, одат од двор до двор и им се полева вода. Песната што ја пеат се вика пеперуга.", source: "Народен обичај", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Денот за гроздобер не се одредува по датум. Се проба по зрно од секој ред и одлуката се носи во лозјето, не дома.", source: "Лозарство", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Кај нас годината има две половини што не се еднакви: онаа во која се работи надвор и онаа во која се јаде она што било собрано.", source: "Народен календар", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Штркот доаѓа кон крајот на март и си оди во август. Селото што има гнездо на оџак ги брои неговите доаѓања како години.", source: "Штрк", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Калемење: врз стар корен се врзува гранче од друго дрво и двете срастуваат во едно. Плодот доаѓа од горното, издржливоста од долното.", source: "Овоштарство", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Дрвото не ја лечи раната, туку ја заградува. Околу неа расте нов слој, а старата повреда останува внатре, затворена и безопасна.", source: "Шумарство", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Скршена коска зараснува така што токму на местото на прскањето станува подебела отколку што била порано.", source: "Анатомија", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Везот на кошулата се работи со броење на нишките. Ако едно место се скине, шарата покажува точно што недостасувало.", source: "Народна носија", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Кога на разбојот ќе се скине нишка, се врзува јазол и се тка понатаму. Јазолот останува во платното и се напипува со прст.", source: "Ткаење", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Здравецот го носи здравјето во името. Се дава на свадба и се носи в коса, а мирисот му останува на прстите долго откако ќе се пушти.", source: "Здравец", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Липата цвета две недели во јуни и целото маало мириса. Цветот се суши и се пие потоа цела зима.", source: "Липа", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Врело: место каде подземната вода излегува одеднаш и со сила, како да врие. Реката Треска почнува од неколку такви.", source: "Хидрологија", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "По оган прво се враќаат тревите чии семиња лежеле во земјата. Дрвјата доаѓаат последни и по свој ред.", source: "Екологија", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Реката по голема вода си го наоѓа старото корито за неколку дена, освен ако во меѓувреме нешто не ѝ го затворило.", source: "Хидрологија", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Кога стара куќа се урива, каменот се вади и оди во нова. Во ѕидовите на селата стојат камења постари од сите куќи што ги паметат.", source: "Народна архитектура", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Медот не се расипува. Најден во сад од пред илјада години, тој сѐ уште е мед, зашто во него нема доволно вода за да живее нешто друго.", source: "Пчеларство", theme: .renewal, subtheme: .madeWhole),
        // MARK: Light
        Passage(text: "Бела квачка дење терат пилина, црна квачка ноќе и збират.", source: "Народна гатанка, одговор: денот и ноќта", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "По зимскиот солстициј денот прво почнува да се должи навечер. Изгревот уште некое време оди нанапред, како да не слушнал.", source: "Астрономија", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Разденување: времето меѓу првата светлина и изгревот, кога сѐ веќе се гледа, а сенка сѐ уште нема.", source: "Македонски јазик", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Самракот во лето трае подолго отколку наесен, зашто сонцето заоѓа под покос агол и подолго му треба да се спушти.", source: "Астрономија", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Во мигот кога последниот раб на сонцето потонува над мирна вода понекогаш блеснува зелена искра. Трае помалку од секунда.", source: "Оптика", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Сонцето се гледа изгреано неколку минути пред навистина да излезе. Воздухот ја свиткува неговата светлина над работ на земјата.", source: "Оптика", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Петелот пее пред мугра, не по неа. Има свој часовник внатре и почнува околу два часа пред да се појави првата светлина.", source: "Зоологија", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Птиците во утринскиот хор не почнуваат заедно. Секој вид влегува во свој час од самракот, така што редот се повторува секое утро.", source: "Орнитологија", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Даница е името на Венера кога се гледа наутро, а Вечерница кога истата се гледа навечер. Долго се сметала за две различни.", source: "Народна астрономија", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Најмногу роса се фаќа во часот пред изгрев, кога земјата е најстудена. Потоа сонцето брзо ја зема назад.", source: "Метеорологија", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Кратко пред изгрев и по заод сѐ изгледа синкаво, зашто до нас стигнува само оној дел од светлината што најмногу се расејува.", source: "Оптика", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Некои цветови се отвораат дури откако ќе се стемни и тогаш мирисаат најсилно, зашто чекаат ноќни пеперуги.", source: "Ботаника", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Кај Кокино над Куманово, пред речиси четири илјади години, на карпата се обележани местата од кои сонцето се гледа како излегува.", source: "Археологија", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Младиот сончоглед го следи сонцето од исток кон запад, а преку ноќ се враќа назад. Кога ќе процвета, застанува свртен кон исток.", source: "Ботаника", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Лозата не брои денови туку топлина. Времето на гроздоберот се пресметува со собирање на сите степени над десет од пролетта наваму.", source: "Лозарство", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Се вели дека мовот стои на северната страна од стеблото. Точно е само толку што таа страна се суши побавно од другите.", source: "Ботаника", theme: .light, subtheme: .readingTheLight),
        Passage(text: "На пладне сенката е најкратка и лежи право кон север. Секој што има стап и рамна земја има и компас.", source: "Астрономија", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Виножитото секогаш стои спроти сонцето. За да го видиш, мораш да си со грб кон сонцето и со лице кон дождот што поминал.", source: "Оптика", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Црвенило на небото навечер обично значи ведрина утредента, зашто времето кај нас доаѓа од запад, а таму воздухот е чист.", source: "Метеорологија", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Пчелите гледаат и ултравиолетова светлина. На многу цветови има линии што водат кон средината, а човечкото око не ги забележува.", source: "Пчеларство", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Светлината што паѓа низ лисја прави на земјата тркалезни дамки, а не дамки со облик на дупките. Секоја дупка е мала слика на сонцето.", source: "Оптика", theme: .light, subtheme: .readingTheLight),
        Passage(text: "На мирно езеро ветерот се гледа пред да се почувствува. Прво се појавува матна лента по површината и оди пред него.", source: "Метеорологија", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Свежиот снег враќа речиси сѐ што ќе падне врз него, па во ведар зимски ден лицето се грее одоздола исто како и одозгора.", source: "Физика", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Пастирите ја читаат висината на месечината како час. Полната месечина изгрева на заод и заоѓа на изгрев, секој пат.", source: "Народна астрономија", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Полн тагар јајца над ѓарамиди.", source: "Народна гатанка, одговор: ѕвездите", theme: .light, subtheme: .lightItself),
        Passage(text: "Ене го, ене го, го немат.", source: "Народна гатанка, одговор: искра", theme: .light, subtheme: .lightItself),
        Passage(text: "Стред море оган горит.", source: "Народна гатанка, одговор: фитил во кандило", theme: .light, subtheme: .lightItself),
        Passage(text: "Едно нешто ноке летат, негде гаде засветвит.", source: "Народна гатанка, одговор: светулка", theme: .light, subtheme: .lightItself),
        Passage(text: "Светулката свети без топлина. Речиси сета енергија што ја троши излегува како светлина, што ниту една наша светилка не го прави.", source: "Ентомологија", theme: .light, subtheme: .lightItself),
        Passage(text: "Месечината не свети сама. Таа враќа околу една десетина од сончевата светлина што ја прима, а другото го задржува.", source: "Астрономија", theme: .light, subtheme: .lightItself),
        Passage(text: "Пламенот на свеќа е потопол на работ отколку во средината, зашто во средината има гориво што сѐ уште не изгорело.", source: "Физика", theme: .light, subtheme: .lightItself),
        Passage(text: "Ноќното небо не е црно. Самиот воздух високо горе испушта слаба светлина, премногу слаба за да ја именуваме.", source: "Астрономија", theme: .light, subtheme: .lightItself),
        Passage(text: "Од сонцето до нас светлината патува околу осум минути. Изгревот што го гледаш веќе се случил додека уште не си станал.", source: "Астрономија", theme: .light, subtheme: .lightItself),
        Passage(text: "Во виножитото нема седум бои. Тие преминуваат едни во други без прекин, а бројот е нешто што луѓето го додале одозгора.", source: "Оптика", theme: .light, subtheme: .lightItself),
        Passage(text: "На окото му требаат околу дваесет минути темнина за да се отвори докрај. Дури тогаш Млечниот Пат се појавува преку целото небо.", source: "Астрономија", theme: .light, subtheme: .lightItself),
        Passage(text: "Кандилото не се пали за да се види. Гори мало пламенче цела ноќ и работата му е да остане запалено до утро.", source: "Народен обичај", theme: .light, subtheme: .lightItself),
        // MARK: Pattern
        Passage(text: "Во македонскиот стресот паѓа на третиот слог од крајот. Додај му наставка на зборот и стресот се поместува за да остане трет.", source: "Македонски јазик", theme: .pattern, subtheme: .counted),
        Passage(text: "Народната музика кај нас брои во нерамни тактови: седум, девет, единаесет. Чекорите не се еднакви, а сепак секој се враќа на своето место.", source: "Народна музика", theme: .pattern, subtheme: .counted),
        Passage(text: "Пет сестрички се бркает, и не может да се стигнет.", source: "Народна гатанка, одговор: игли за плетење", theme: .pattern, subtheme: .counted),
        Passage(text: "Имам сестрица со дванаесет ѕуници спиет.", source: "Народна гатанка, одговор: буре со обрачи", theme: .pattern, subtheme: .counted),
        Passage(text: "Гумното е тркалезен утабан круг на кој воловите одат в круг додека зрното не се одвои од сламата. Секој круг е измерен со чекори.", source: "Земјоделство", theme: .pattern, subtheme: .counted),
        Passage(text: "Броеницата има точно определен број јазли за да не мора да се брои со глава. Прстот знае каде застанал.", source: "Народен обичај", theme: .pattern, subtheme: .counted),
        Passage(text: "Кошницата се плете околу непарен број прачки. Со парен број плетењето се затвора врз себе и шарата не се врзува.", source: "Занает", theme: .pattern, subtheme: .counted),
        Passage(text: "Дрвото пишува по еден прстен на година. Во сушна година прстенот е потенок, па во пресекот стои запис за времето.", source: "Шумарство", theme: .pattern, subtheme: .counted),
        Passage(text: "Моликата носи по пет иглички во снопче, црниот бор по две. Борот се познава по бројот пред да му се погледне шишарката.", source: "Ботаника", theme: .pattern, subtheme: .counted),
        Passage(text: "Ливчињата на многу цветови доаѓаат во еден ист ред броеви: три, пет, осум, тринаесет. Растението не брои, но излегува исто.", source: "Ботаника", theme: .pattern, subtheme: .counted),
        Passage(text: "Ткајачката не мери со метар. Ширината на платното е онолкава колкав е разбојот, а сето друго се смета во нишки.", source: "Ткаење", theme: .pattern, subtheme: .counted),
        Passage(text: "Овците се бројат на враќање во трлото, не на паша. Бројот на влезот е единствената проверка што вреди нешто.", source: "Овчарство", theme: .pattern, subtheme: .counted),
        Passage(text: "Ни ткаено, ни предено, ни шиено, по куќи растурено.", source: "Народна гатанка, одговор: пајажина", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Отзгора небо, отздола небо, во стреде ливада.", source: "Народна гатанка, одговор: зелник", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Саќето е од шестоаголници, зашто со шест страни ќелиите легнуваат една до друга без ниту едно празно место меѓу нив.", source: "Пчеларство", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Тапанот има два гласа. Од едната страна се удира со дебел стап, од другата со тенка прачка, па еден инструмент држи и потпора и брзина.", source: "Народна музика", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Иконостасот во Свети Спас во Скопје е резбан во орево од мијачки мајстори, во неколку слоја длабочина, ликови еден зад друг.", source: "Резбарство", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Камењата на калдрмата не се сечени. Мајсторот го врти секое додека не најде страна што пасува, и потоа ниедно не се заменува со друго.", source: "Занает", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Ѕид без малтер држи со сопствената тежина, ако секој камен лежи врз два долни. Тоа е целата тајна и трае со векови.", source: "Народна архитектура", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Во мозаик секое камче е сечено за своето место. Ако едно се извади, останува дупка со облик што ниту едно друго не го исполнува.", source: "Археологија", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Свод се ѕида врз дрвено скеле, а последен влегува каменот на теме. Штом тој ќе седне, скелето станува непотребно.", source: "Градежништво", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "На разбој има две нишки со различни работи. Основата стои затегната по целата должина, јатокот оди напред-назад, а платното е местото каде се среќаваат.", source: "Ткаење", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Ќерамидите се редат со преклоп, па секоја ја држи следната и дождот нема каде да се вовре меѓу нив.", source: "Народна архитектура", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Плетот се плете околу забодени колци, наизменично од двете страни. Ниту една прачка не држи сама, а целиот плет стои.", source: "Занает", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Бела ливада со црни цвеќа.", source: "Народна гатанка, одговор: испишана книга", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Ѕ, Ѓ и Ќ ги нема во ниедна друга азбука што денес се пишува. Ѕ е задржано од најстарото словенско писмо, каде значело истото.", source: "Историја на јазикот", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Македонскиот е единствен меѓу словенските јазици со три определени члена: книгата, книгава и книгана. Едната е книга воопшто, другите две се место.", source: "Македонски јазик", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Дојде значи дека си бил таму и си видел. Дошол значи дека така ти кажале. Јазикот бара да кажеш од каде ти е веста.", source: "Македонски јазик", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Во македонскиот нема инфинитив. Не постои гол глагол; секој мора да си го носи лицето со себе пред да влезе во реченица.", source: "Македонски јазик", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Го видов Марко. Предметот се јавува двапати, еднаш како кратка заменка и еднаш со име, и на јазикот тоа не му е премногу.", source: "Македонски јазик", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Секое растение носи две имиња: едното го дели со роднините, другото е само негово. Второто без првото не значи ништо.", source: "Номенклатура", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Едно исто цвеќе има поинакво име во две соседни села. Латинското име е измислено токму за да престане тоа.", source: "Ботаника", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Вардарец е студениот ветер што слегува по долината на Вардар. Југото е топлото што доаѓа од спротивната страна. И двата се именувани по правецот.", source: "Метеорологија", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Имињата на местата обично кажуваат што има таму. Вруток е извор, Бигорски е бигор, а секоја Тумба е могила.", source: "Топонимија", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "За луѓе се брои поинаку: двајца, тројца, четворица. Тие форми не се употребуваат за ништо друго на светот.", source: "Македонски јазик", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Плејадите кај нас се викаат Квачка со пилиња, а седумте ѕвезди на север се Голема Кола. Небото е именувано од двор, не од книга.", source: "Народна астрономија", theme: .pattern, subtheme: .orderNamed),
        // MARK: Ground
        Passage(text: "Без една работа ни човек, ни господ живјат.", source: "Народна гатанка, одговор: место", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Смолницата во Пелагонија е тешка црна земја. Во суша се пука на длабоки процепи, во дожд лепне на секој чекор. Иста почва, две работи.", source: "Педологија", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Црвеницата врз варовник е сето што останало откако каменот се растворил. Црвенилото доаѓа од железо што не заминало со водата.", source: "Педологија", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Чешма доаѓа од персиски збор што значи и око и извор. И двете се отвор низ кој нешто истекува без да престане.", source: "Етимологија", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Дождовните црви за една година поминуваат низ себе неколку тони земја на хектар и ја враќаат нагоре, врз површината.", source: "Педологија", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Врз Галичица нема реки. Секој дожд поминува право низ каменот и излегува подолу, веќе како извор во езерото.", source: "Геологија", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Плодниот слој се создава по неколку сантиметри во неколку векови. Секоја лопата од него е постара од секој што ја држел.", source: "Педологија", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Овците ноќе се затвораат на нивата, а не во трлото, и се преместуваат по неколку дена. Земјата се ѓубри без ништо да се носи.", source: "Овчарство", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Ако земјата стисната в рака остане грутка, време е за орање. Ако се распадне меѓу прстите, уште не е.", source: "Земјоделство", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Овче Поле е рамнина без река. Житото таму зависи само од тоа колку дожд паднал во мај и од ништо друго.", source: "Географија", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Кочанскиот ориз не се наводнува туку се плави. Нивата се држи под вода додека стеблото не порасне над неа.", source: "Земјоделство", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Лозата сака сиромашна земја. Во богата почва пушта лист и прачка, во камениста дава грозје. Мачењето ѝ е потребно.", source: "Лозарство", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Огниште значи и местото каде гори огнот и куќата од која си. Кога ќе се рече дека некој си го оставил огништето, не се мисли на каминот.", source: "Македонски јазик", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Крај значи и завршеток и предел. Истиот збор го носи местото од каде си и работ каде нештата запираат.", source: "Македонски јазик", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "По везот на кошулата се познавало од кое село е човекот. Шарата не била украс туку адреса, читлива од далеку.", source: "Народна носија", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Во Галичник свадбите се правеле еднаш годишно, на Петровден, зашто тогаш мажите што работеле на страна се враќале дома.", source: "Народен обичај", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Многу презимиња кај нас се направени од името на селото од кое дошло семејството. Човек го носи местото пред себе, во исправа.", source: "Ономастика", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Маало е делот од градот што има своја чешма и своја црква, и по правило во него секој знае кој кому припаѓа.", source: "Народна архитектура", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Секое село има еден ден во годината кога се враќаат и оние што одамна не живеат таму. Тој ден се вика селска слава.", source: "Народен обичај", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "На стрмните ридови нивите се правеле во тераси, потпрени со сув ѕид. Земјата се качувала нагоре во кошници и се задржувала горе.", source: "Земјоделство", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Двете мали езера високо на Пелистер народот ги вика очи. Планината не се именува по врвот туку по тоа со што гледа.", source: "Топонимија", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Чешмата на влезот во селото често е постара од куќите зад неа. Селото се преместувало, а изворот останувал каде што бил.", source: "Народна архитектура", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Куќите во стрмните села се ѕидаат една над друга, така што покривот на долната е двор на горната.", source: "Народна архитектура", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Мијаците, Брсјаците и другите стари имиња на области кај нас се постари од сите граници повлечени преку нив.", source: "Етнологија", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Бавча доаѓа од персиското бахче, мала градина. Зборот патувал преку турскиот и останал кај нас за парчето земја зад куќата.", source: "Етимологија", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Бачилото се отвора секое лето на исто место на планината и се затвора наесен. Целата зима стои празно, а сепак нечие.", source: "Овчарство", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Лозјето бара работа дванаесет месеци, а дава три недели. Оставено две години, тешко се враќа во ред.", source: "Лозарство", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Изворите кај Свети Наум излегуваат право во езерото, па водата таму останува студена и на средина на јули.", source: "Хидрологија", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Кошниците се вртат кон исток, за пчелите утрото да излетаат порано и да го фатат целиот ден.", source: "Пчеларство", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Визбата не се грее и не се лади. Земјата околу неа држи иста температура цела година, па тоа е единствената соба што не знае кој месец е.", source: "Народна архитектура", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Над дворот се води лоза на дрвена решетка. Лете прави сенка, а зиме, штом ќе го фрли листот, го пушта сонцето долу.", source: "Народна архитектура", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Старите сорти јаболка опстојуваат само додека некој ги калеми понатаму. Дрвото завршува, сортата продолжува преку гранче.", source: "Овоштарство", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Градината зад куќата не се планира докрај. Она што останало од лани само никнува, а работата на градинарот е да одбере што да остави.", source: "Градинарство", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Бунарот се покрива со капак не поради водата туку поради лисјето. Отворен бунар за една есен станува неупотреблив.", source: "Занает", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Тиквешките лозја се свртени кон југ. Падината се бира пред сортата, зашто сортата може да се смени, падината не.", source: "Лозарство", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Во постудените краишта смоквата пред првиот мраз се приведува кон земја и се затрупува. Напролет се откопува и се крева пак.", source: "Овоштарство", theme: .ground, subtheme: .aKeptPlace),
        // MARK: Travel
        Passage(text: "Шило бодило, низ гора ходило, траг не оставило.", source: "Народна гатанка, одговор: пчела", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Репувот се фаќа за волната на овцата и патува со неа неколку дена, додека некој не ја исчешла. Тоа му е целата замисла.", source: "Ботаника", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Јаворовото семе паѓа вртејќи се како елиса. Вртењето му дава време ветерот да го однесе настрана од дрвото што го пуштило.", source: "Ботаника", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Семето на глуварчето виси под чадорче од влакненца. Над него се создава мало виорче што го држи во воздух подолго отколку што би паѓало.", source: "Ботаника", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Птиците ги јадат плодовите на дренот и на калината, а семките ги оставаат недопрени. Оној што го изел плодот го посадил дрвото.", source: "Орнитологија", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Некои треви носат долго осилче што се врти кога влажноста се менува. Со тоа вртење семето само се завртува во земјата.", source: "Ботаника", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Зрното борова прашина има од двете страни по едно меурче воздух. Со нив стигнува подалеку отколку што дрвото е високо.", source: "Ботаника", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Печурката испушта спори толку лесни што остануваат во воздухот со денови и слегуваат каде што нема кој да ги видел како дошле.", source: "Микологија", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Овчарот носи семе без да знае: во волната, во опинците и меѓу зрната што ги дава на стадото. Пасиштето патува со него.", source: "Овчарство", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Реката ги остава семињата на завоите. Затоа по бреговите растат други растенија отколку на ридот што е точно над нив.", source: "Екологија", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Семето на трската е ситно колку прав и лета над водата со километри. Оттаму трската е прва на секој нов брег.", source: "Ботаника", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "По патиштата секое лето се шират растенија што дошле со камион, со сено или со семе за добиток. Патот е и тој начин на сеење.", source: "Екологија", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Ни се водит, ни се терат, трага праит.", source: "Народна гатанка, одговор: сврдел", theme: .travel, subtheme: .theRoad),
        Passage(text: "Стариот римски пат од Јадранот кон Солун поминувал низ Хераклеја и низ Лихнид. И денес се оди по истите превои, зашто други нема.", source: "Историја", theme: .travel, subtheme: .theRoad),
        Passage(text: "Ановите во старата чаршија имаат двор во средина: долу се врзувале коњите, горе спиеле луѓето. Патникот и товарот преноќувале под ист покрив.", source: "Народна архитектура", theme: .travel, subtheme: .theRoad),
        Passage(text: "Долината на Вардар е единствениот низок премин од морето кон север. По неа поминале и ветровите, и птиците, и сите патишта.", source: "Географија", theme: .travel, subtheme: .theRoad),
        Passage(text: "Кираџија бил оној што со коњи носел товар меѓу градовите. Работата не била да стигне прв, туку да стигне со сето што тргнало.", source: "Турцизам во македонскиот", theme: .travel, subtheme: .theRoad),
        Passage(text: "На тргнување кај нас се вели Со среќа, а не збогум. Разликата меѓу двете е во тоа што првото претпоставува враќање.", source: "Македонски јазик", theme: .travel, subtheme: .theRoad),
        Passage(text: "Стадата зимуваат долу и лете се качуваат на планина. Патеките по кои се движат со векови се познаваат по тоа што на нив трева не фаќа.", source: "Овчарство", theme: .travel, subtheme: .theRoad),
        Passage(text: "Патник е оној што е на пат. Јазикот не бара да се каже каде оди; доволно му е тоа што не е дома.", source: "Македонски јазик", theme: .travel, subtheme: .theRoad),
        Passage(text: "Раскрсница го носи крстот во името. Тоа е местото каде патот се крши на неколку и од каде се гледа на сите страни одеднаш.", source: "Етимологија", theme: .travel, subtheme: .theRoad),
        Passage(text: "Магарето по стрмно само оди во цик-цак наместо право нагоре. Со тоа секој чекор му е за малку помалку качување.", source: "Зоологија", theme: .travel, subtheme: .theRoad),
        Passage(text: "Човек оди со околу пет километри на час и тоа не се сменило откако се оди. Сите стари растојанија се мерени со тој број.", source: "Географија", theme: .travel, subtheme: .theRoad),
        Passage(text: "Планинските премини кај нас се отвораат и затвораат со снегот, па меѓу две села може да е поблиску преку лето отколку преку зима.", source: "Географија", theme: .travel, subtheme: .theRoad),
        Passage(text: "Печалбар е оној што оди на работа далеку и се враќа. Зборот стои на печал, па во него е кажано и одењето и колку чини.", source: "Македонски јазик", theme: .travel, subtheme: .farOff),
        Passage(text: "Гурбет значи да си далеку од своето. Зборот именува состојба, не место: може да си на гурбет и во соседниот град.", source: "Турцизам во македонскиот", theme: .travel, subtheme: .farOff),
        Passage(text: "Со наставката -он нештото се става далеку од двајцата што зборуваат: човекот, човеков, човекон. Третото значи оној, онаму.", source: "Македонски јазик", theme: .travel, subtheme: .farOff),
        Passage(text: "Во приказната за Силјан Штркот човек се претвора во штрк, лета со јатото преку море и се враќа дома со истото јато напролет.", source: "Приказна запишана од Марко Цепенков", theme: .travel, subtheme: .farOff),
        Passage(text: "Старци со бели бради не может да се стигнет.", source: "Народна гатанка, одговор: бранови", theme: .travel, subtheme: .farOff),
        Passage(text: "Јагулите од нашите езера се мрестат во Атлантикот и никаде на друго место. Малите се враќаат по пат што никој не им го покажал.", source: "Ихтиологија", theme: .travel, subtheme: .farOff),
        Passage(text: "Штркот од нашите оџаци зимува во Африка. Тој ја поминува целата година меѓу две села што ништо друго не ги поврзува.", source: "Орнитологија", theme: .travel, subtheme: .farOff),
        Passage(text: "Кашкавал доаѓа од италијанското качокавало, сирење на коњ, зашто се сушело обесено преку прачка во парови. Името патувало со сирењето.", source: "Етимологија", theme: .travel, subtheme: .farOff),
        Passage(text: "Ајвар доаѓа од турскиот збор за кавијар. Со векови значело риба, а кај нас на крајот значи пиперка.", source: "Етимологија", theme: .travel, subtheme: .farOff),
        Passage(text: "Пиперката, доматот и пченката ги немало овде пред петстотини години. Најдомашното јадење е составено од работи што допатувале.", source: "Историја", theme: .travel, subtheme: .farOff),
        Passage(text: "Светлината од најблиската ѕвезда до нашата патува повеќе од четири години. Секој поглед нагоре е гледање во нешто заминато одамна.", source: "Астрономија", theme: .travel, subtheme: .farOff),
        Passage(text: "Прилепскиот тутун се продавал далеку од местото каде растел. Оние што го береле никогаш не го виделе оној што го купувал.", source: "Историја", theme: .travel, subtheme: .farOff),
        // MARK: Meeting
        Passage(text: "Кај си? е поздрав, не прашање. Буквално значи каде си, а се кажува токму на човекот што веќе стои пред тебе.", source: "Македонски јазик", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Со прави цело гнездо зборови: соговорник, соживот, содружник, сограѓанин. Ниту еден од нив не може да постои со еден човек.", source: "Македонски јазик", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Здраво е поздрав направен од придавка. Не прашуваш и не бараш ништо, само го изговараш зборот здравје врз оној пред тебе.", source: "Македонски јазик", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Стрелките на часовникот се среќаваат единаесет пати во дванаесет часа, никогаш дванаесет. Едната средба секогаш се губи по пат.", source: "Механика", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Сонцето и месечината изгледаат еднакво големи на небото само затоа што едното е четиристотини пати поголемо и толку пати подалеку.", source: "Астрономија", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Кога Црна Река влегува во Вардар, двете води одат една до друга подолго време без да се измешаат, зашто носат различна топлина.", source: "Хидрологија", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Пред да има часовници луѓето се договарале да се најдат на пладне. Пладнето е единствениот час што секој може сам да го најде.", source: "Историја", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Покана на кафе кај нас не е за кафето. Тоа е најкраткиот начин да се каже дека има време и дека тоа време е за некого.", source: "Народен обичај", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Камениот мост со векови бил единственото место каде двата брега на градот се допираат. Секој што одел од едниот кон другиот поминувал таму.", source: "Историја", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Две пчели што се сретнуваат во кошницата застануваат и се допираат со пипалките. Тоа трае помалку од секунда и не се пропушта.", source: "Пчеларство", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Кога ќе се сретнат две стада на тесна патека, овчарите застануваат прво тие, а дури потоа стадата поминуваат едно покрај друго.", source: "Овчарство", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Небото и водата на езеро наутро имаат иста боја и работ меѓу нив исчезнува. Има половина час кога не се знае каде престанува едното.", source: "Метеорологија", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Две сестрици през плет се целиват, и не можат да се видат.", source: "Народна гатанка, одговор: очите", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Во двогласното пеење едниот глас се движи, а другиот стои на едно место цело време. Ниту едниот сам од нив не е песна.", source: "Народна музика", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Тапанот и зурлата се свират само заедно и само надвор. Ниту еден од двата не е инструмент за соба.", source: "Народна музика", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "На Дојранското Езеро рибарите ѕидале прегради од трска во плитката вода и со припитомени корморани ја натерувале рибата да влезе внатре.", source: "Рибарство", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Корените на дрвото и нишките на печурката се спојуваат под земја. Дрвото дава шеќер, печурката дава вода. Ниту едното не се снаоѓа само.", source: "Микологија", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Лишајот е две суштества во едно: габа што прави куќа и алга што прави храна. Ниту една од двете не живее сама на гол камен.", source: "Ботаника", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Дивата смоква и една многу мала оса не можат едно без друго. Осата се измолува внатре во плодот, а плодот без неа не се врзува.", source: "Ботаника", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Волот се впрега во пар и никогаш сам. Јаремот е направен за двајца и не оди право ако едниот влече посилно од другиот.", source: "Земјоделство", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Шарпланинецот не ги тера овците туку оди со нив. Работата му е да биде видлив од далеку за оној што гледа од страна.", source: "Овчарство", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Младата лоза не стои сама и ѝ се дава колец додека не се здрви. Кога ќе може да се држи, колецот се вади и оди на друга.", source: "Лозарство", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Мостот има два брега. Ако едниот се одземе, мостот не станува пократок туку престанува да биде мост.", source: "Градежништво", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Врз буре обрачот и даските се држат меѓусебно. Ако се извади обрачот, даските паѓаат; ако се извадат даските, обрачот нема што да стега.", source: "Занает", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Домаќин значи и стопан на куќата и оној што прима гости. Јазикот не ги раздвојува тие две работи и не бара да се раздвојат.", source: "Македонски јазик", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Орото се игра во отворен полукруг, никогаш во затворен круг. Отворот е таму за да може некој да се фати подоцна.", source: "Народна музика", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Муабет е разговор што нема цел освен самиот себе. Зборот дошол преку турскиот и значи и зборувањето и задоволството од него.", source: "Турцизам во македонскиот", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Довидување е составено од до и видување. Разделбата е именувана по следната средба, а не по онаа што сега завршува.", source: "Македонски јазик", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Добредојде значи буквално дека добро си дошол. Не се кажува на прагот туку откако веќе си влегол и си седнал.", source: "Македонски јазик", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Гостинот се пречекува со леб и сол пред да седне. Двете работи што куќата ги има секогаш се и двете што прв ги добива туѓиот.", source: "Народен обичај", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Пред кафето се носи вода, и за неа не се прашува. Таа е единственото нешто во куќата што се дава без покана.", source: "Народен обичај", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Изволете се кажува кога нешто се подава и кога некој се пушта прв да влезе. Еден збор ги врши обете работи.", source: "Македонски јазик", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "На здравје се кажува и по кревање чаша и по кивање. Истата желба служи во две сосема различни прилики, без ништо да се менува.", source: "Македонски јазик", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Пријатно се кажува пред јадење и на заминување. Тоа не е ниту поздрав ниту наздравица, туку желба некому да му биде убаво без тебе.", source: "Македонски јазик", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "На постар и на непознат му се обраќаме со Вие. Еден човек за миг станува множина, и во тоа е сета учтивост.", source: "Македонски јазик", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Обувките се оставаат на врата. Тоа не е за подот; тоа е знак дека веќе не си на пат туку кај некого.", source: "Народен обичај", theme: .meeting, subtheme: .theMannersOfIt),
        // MARK: Kinship
        Passage(text: "Четворица браќа в една кошуља не может да се видет.", source: "Народна гатанка, одговор: јатки од орев", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Крушата пот круша падинат.", source: "Пословица, Зборник на Миладиновци, 1861", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Две гранки што со години се тријат една од друга може да срастат и потоа да делат сок. Оттогаш не се знае која е чија.", source: "Шумарство", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Побратимството не се наследува туку се склучува. Двајца што не се роднини стануваат роднини со збор кажан пред сведоци.", source: "Народен обичај", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Една тревка изгледа како едно растение, а под земја стотина стебленца излегуваат од иста подземна жица и се едно.", source: "Ботаника", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Тополите наредени покрај нива често се едно дрво. Сите пуштиле од ист корен и наесен го менуваат листот заедно.", source: "Ботаника", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Во старата куќа живееле три или четири колена под ист покрив, со една каса и една трпеза. Тоа се викало задруга.", source: "Етнологија", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Во септември цела улица пече пиперки одеднаш. Чадот, тепсиите и рацете се делат, па и мирисот е заеднички.", source: "Готварство", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "На бачило овците на неколку куќи се молзат заедно, а сирењето се дели според тоа колку млеко дала секоја. Сметката се води наум.", source: "Овчарство", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Дрвјата од ист вид често си ги спојуваат корените под земја. Затоа пенушка од исечено дрво може да остане жива со години.", source: "Шумарство", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Главиците лук се плетат заедно за да висат. Ниту една не се држи сама, а плетенката се држи и кога половината се потрошени.", source: "Готварство", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Кошницата е едно суштество со педесет илјади тела. Ниту едно од нив не преживува само надвор дури ни едно лето.", source: "Пчеларство", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Чичко е од таткова страна, вујко од мајчина. Јазикот бара да се знае преку кого си роднина пред да се каже дека си.", source: "Македонски јазик", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Мајко, брате, сине. Кога му се обраќаш некому по име, името се менува, и тој облик служи само за обраќање.", source: "Македонски јазик", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Дивиот тимјан по сувите ридови се вика мајчина душица. Растението ги носи и мајката и душата во своето име.", source: "Ботаника", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Аманет е нешто дадено некому на чување со целосна доверба. Зборот не именува предмет туку она што со предметот се презема.", source: "Турцизам во македонскиот", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Комшилук не значи сосед туку соседството како однос. Јазикот има посебен збор за врската, а не само за човекот.", source: "Турцизам во македонскиот", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Ортак е оној со кого си влегол во иста работа. Зборот се употребува и за занает и за пријателство, без да се менува.", source: "Турцизам во македонскиот", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Постар човек му вели сине и на туѓо дете. Зборот излегол од родот и станал начин на обраќање кон секој помлад.", source: "Македонски јазик", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Род значи и потомство и она што нивата дава. Луѓето и житото се броени со ист збор, и во двата случаја се мисли на продолжување.", source: "Македонски јазик", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Свои значи и своите луѓе и она што ти припаѓа. Кога за некого ќе се рече дека е свој, не се тврди роднинство туку дека не е туѓ.", source: "Македонски јазик", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Домашни се сите што спијат под ист покрив, без оглед на крвта. Покривот е тој што ги именува, не потеклото.", source: "Македонски јазик", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Во село човек често се знае по прекарот на дедото. Името од исправата е за туѓите, а прекарот е за оние што знаат од каде е.", source: "Ономастика", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Стрина, тетка и вујна се три различни жени. Секоја има свое име според тоа преку кого влегла во куќата.", source: "Македонски јазик", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Брат брата не ранит, тешко кој го немат.", source: "Пословица, Зборник на Миладиновци, 1861", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Два камења љути не мељат брашно.", source: "Пословица, Зборник на Миладиновци, 1861", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Горниот камен на воденица се врти, долниот стои на место. Мелење има само ако едниот се движи, а другиот трпи под него.", source: "Занает", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Ножиците се две сечила што не сечат ниту едно само. Работата ја врши местото каде се допираат, не работ.", source: "Занает", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Секој има двајца родители, четворица дедовци и баби, осуммина пред нив. Десет колена наназад тоа се повеќе луѓе отколку што селото имало.", source: "Аритметика", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Кога двајца носат тешко по скали, оној одоздола носи повеќе, но оној одозгора одлучува колку брзо ќе се оди.", source: "Физика", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Два славеја од соседни грмушки пеат наизменично и не се преклопуваат. Секој чека другиот да заврши, цела ноќ.", source: "Орнитологија", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Кога двајца одат заедно подолго време, чекорите им се израмнуваат без да се договорат и без некој да забележи кога.", source: "Физиологија", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Во чун со две весла, ако едниот повлече посилно, чунот се врти в круг. Насоката е нешто што се прави заедно или воопшто не.", source: "Механика", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Две сестри в една дупка.", source: "Народна гатанка, одговор: крилата на вратата", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Пилата за големо дрво има рачка на двата краја. Едниот влече, другиот пушта, и никој од двајцата не смее да турка.", source: "Занает", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Кога едниот почне да зборува потивко, другиот несвесно го спушта гласот по него. Тоа станува за неколку реченици и никој не го предлага.", source: "Фонетика", theme: .kinship, subtheme: .twoPeople),
        // MARK: Peace
        Passage(text: "Глуво доба е часот на ноќта именуван по тоа што не се слуша. Времето е кажано преку сетило, не преку часовник.", source: "Македонски јазик", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Затишје е краткото време кога ветерот застанува пред бура. Има свој збор токму затоа што не е исто со мир.", source: "Македонски јазик", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Русалиите од Гевгелиско играле низ дванаесетте некрстени денови и додека биле во оделото не смееле да проговорат со никого.", source: "Народен обичај", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Клепалото е дрвена штица што се удира со чекан наместо ѕвоно. Со векови повикот на собирање бил дрвен, зашто друг не бил дозволен.", source: "Историја", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Трепетликата е именувана по треперењето. Листот ѝ виси на сплескана дршка, па се врти и при ветер што не се чувствува на лицето.", source: "Ботаника", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Свежиот снег го голта звукот. Меѓу снегулките останува воздух, и тој воздух ги прима брановите наместо да ги врати назад.", source: "Акустика", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Наутро над мирна вода се слуша разговор од другиот брег. Студениот слој долу ја свиткува звучната бранова надолу и таа не бега нагоре.", source: "Акустика", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Ромони е глагол што го прави звукот што го именува. Се вели за вода, за дожд по лисје и за разговор што се слуша, но не се разбира.", source: "Македонски јазик", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Шума и шум стојат еден до друг во речникот. Гората е именувана со збор што личи на звукот што го прави кога никој не зборува.", source: "Македонски јазик", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Кавалот се свири со воздух однесен странично преку остар раб. Во тонот секогаш се слуша и здивот, не само нотата.", source: "Народна музика", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Молчи е глагол, молкот е именка. Јазикот му дал и дејство и состојба, како да е нешто што некој го прави, а не нешто што недостасува.", source: "Македонски јазик", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Премолчено е она за што двајцата знаат, а никој не го кажал. Договор може да биде премолчен и сепак да важи меѓу нив.", source: "Македонски јазик", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Мир значи и спокој и крај на војна, а истиот збор стои и во заповедта мирно, кога човек треба само да застане.", source: "Македонски јазик", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Примирје е мир со при- пред себе: доведен близу, но уште невлезен во куќата. Зборот сам кажува дека работата не е завршена.", source: "Македонски јазик", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Помирување значи мирот да се направи повторно. Наставката кажува дека тоа веќе го имало еднаш меѓу истите двајца.", source: "Македонски јазик", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Меѓа и меѓу се од ист корен. Границата на две ниви е именувана со зборот за средина, како да е место, а не линија.", source: "Етимологија", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Синор е границата на нива, збор земен од грчкиот. Каде престанува твоето и почнува соседовото добива посебно име и се памети.", source: "Етимологија", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "На Прочка помладите одат кај постарите и бараат прошка, а одговорот е Господ да прости. Постот не почнува пред тоа да е свршено.", source: "Народен обичај", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Аман дошол преку турскиот од арапски, каде значи безбедност. Во народните песни се пее како збор со кој се моли нешто да престане.", source: "Турцизам во македонскиот", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Одмор е составено од од и умор. Не значи собирање сила туку одземање на замореноста, што е поинаква работа.", source: "Етимологија", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Доста е еден збор со кој се запира сѐ. Не кажува дека има многу, туку дека повеќе не е потребно.", source: "Македонски јазик", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Во физиката телото во мирување не е тело без сили врз себе. Тоа е тело кај кое силите се израмниле една со друга.", source: "Физика", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Полека е и прилог и молба. Кога некој ќе рече полека, не бара да се оди побавно туку да се брза помалку.", source: "Македонски јазик", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Мирен човек не значи тивок. Значи човек со кого нема караница, што е особина на двајца, а се припишува на еден.", source: "Македонски јазик", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Најсладко, најблаго на таљур не се клаат.", source: "Народна гатанка, одговор: сон", theme: .peace, subtheme: .atEase),
        Passage(text: "Едно нешто летат, високо летат, кога ке паднит како на памбук.", source: "Народна гатанка, одговор: пеперуга", theme: .peace, subtheme: .atEase),
        Passage(text: "Ќеиф е состојба на задоволство без причина. Дошол преку турскиот од арапски и не се заменува со ниту еден домашен збор.", source: "Турцизам во македонскиот", theme: .peace, subtheme: .atEase),
        Passage(text: "Мерак е волја за нешто заради самото него. Кога некој работи со мерак, тоа најпрво значи дека не му се брза.", source: "Турцизам во македонскиот", theme: .peace, subtheme: .atEase),
        Passage(text: "Ладовина е местото под дрво каде не удира сонце. Лете тоа не е сенка туку предел, и затоа има свое име.", source: "Македонски јазик", theme: .peace, subtheme: .atEase),
        Passage(text: "Миндерот е ниската клупа со душеци покрај ѕидот. Направен е за да се седи со часови, а не за да се седне за момент.", source: "Народна архитектура", theme: .peace, subtheme: .atEase),
        Passage(text: "По ручек во горештина се лежи додека не попушти. Работата чека, и сите знаат дека чека, па никој не се извинува.", source: "Народен обичај", theme: .peace, subtheme: .atEase),
        Passage(text: "Кон вечер покрај езеро ветерот се врти и почнува да дува од водата кон брегот. Тоа се случува секој ден, отприлика во исто време.", source: "Метеорологија", theme: .peace, subtheme: .atEase),
        Passage(text: "Мачката го наоѓа најтоплото место во куќата поточно од која било направа, и го наоѓа пред некој да забележи дека го има.", source: "Зоологија", theme: .peace, subtheme: .atEase),
        Passage(text: "Кога ќе седнеш на камен во сенка, тој прво е студен, а потоа станува топол колку тебе. Тоа трае неколку минути и потоа престанува да се забележува.", source: "Физика", theme: .peace, subtheme: .atEase),
        Passage(text: "Во најголема горештина стадото застанува во круг со главите кон средината и не мрда до кон четири часот. Тоа се вика пладнување.", source: "Овчарство", theme: .peace, subtheme: .atEase),
        Passage(text: "Човек поминува околу третина од животот спиејќи. Тоа е единственото нешто што сите го прават во иста мера, без исклучок.", source: "Физиологија", theme: .peace, subtheme: .atEase),
    ]
}
